def seed_inspection_items(apps, schema_editor):
    """内置巡检项按 code 幂等写入；目录只在 ops/inspection_items.py 维护一份。"""
    from ops.inspection_items import BUILTIN_INSPECTION_ITEMS

    Item = apps.get_model('ops', 'InspectionItem')
    for definition in BUILTIN_INSPECTION_ITEMS:
        defaults = {key: value for key, value in definition.items() if key != 'code'}
        defaults['is_builtin'] = True
        Item.objects.update_or_create(code=definition['code'], defaults=defaults)


def unseed_inspection_items(apps, schema_editor):
    from ops.inspection_items import BUILTIN_INSPECTION_ITEMS

    Item = apps.get_model('ops', 'InspectionItem')
    Item.objects.filter(code__in=[item['code'] for item in BUILTIN_INSPECTION_ITEMS], is_builtin=True).delete()


